GN['fr.es'] = {
A1: [
 {t:'Los pronombres y los verbos être y avoir',
  b:`<p>Los pronombres sujeto son [[je]] (yo), [[tu]] (tú), [[il]] / [[elle]] (él / ella), [[on]] (nosotros, uno), [[nous]] (nosotros), [[vous]] (vosotros, usted), [[ils]] / [[elles]] (ellos / ellas).</p><div class="tblwrap"><table><tr><th></th><th>être (ser / estar)</th><th>avoir (tener / haber)</th></tr><tr><td>je</td><td>[[suis]]</td><td>[[ai]] (j'ai)</td></tr><tr><td>tu</td><td>[[es]]</td><td>[[as]]</td></tr><tr><td>il / elle / on</td><td>[[est]]</td><td>[[a]]</td></tr><tr><td>nous</td><td>[[sommes]]</td><td>[[avons]]</td></tr><tr><td>vous</td><td>[[êtes]]</td><td>[[avez]]</td></tr><tr><td>ils / elles</td><td>[[sont]]</td><td>[[ont]]</td></tr></table></div><p class="tip">A diferencia del español, el pronombre sujeto es obligatorio. Delante de vocal, [[je]] se convierte en [[j']]: [[J'ai faim.]] = Tengo hambre.</p>`,
  ex:['Soy estudiante.','Eres muy amable.','Tenemos un coche.','Ella tiene dos hijos.'],
  q:['«Estoy cansado»:','«Tenemos un gato»:']},
 {t:'El género y los artículos',
  b:`<p>Como en español, cada sustantivo es masculino o femenino, pero el género no siempre coincide: [[le livre]] (masculino), [[la table]] (femenino). Delante de vocal ambos se convierten en [[l']]: [[l'école]]. En plural: [[les]].</p><p>El artículo indefinido es [[un]] (masculino), [[une]] (femenino) y [[des]] (plural): [[un frère]], [[une sœur]], [[des enfants]].</p><p class="tip">La [[-s]] del plural normalmente no se pronuncia: [[le livre]] y [[les livres]] suenan igual salvo el artículo.</p>`,
  ex:['El libro es interesante.','La mesa es grande.','Tengo un hermano y una hermana.','Los niños juegan.'],
  q:['«La casa» (femenino):','«Un perro» (masculino):']},
 {t:'El presente de los verbos en -er',
  b:`<p>La mayoría de los verbos franceses terminan en -er. Quita -er y añade las terminaciones: [[je parle]], [[tu parles]], [[il parle]], [[nous parlons]], [[vous parlez]], [[ils parlent]].</p><p>Las terminaciones -e, -es, -ent no se pronuncian, así que [[parle]], [[parles]] y [[parlent]] suenan igual.</p><p class="tip">Los verbos en -ger conservan la e delante de -ons: [[nous mangeons]].</p>`,
  ex:['Vivo en París.','¿Hablas francés?','Nos gusta el café.','Ellos trabajan mucho.'],
  q:['«tú hablas» (parler):','«nosotros comemos» (manger):']},
 {t:'La negación y las preguntas',
  b:`<p>La negación rodea el verbo: [[ne]] … [[pas]]: [[Je ne parle pas anglais.]] Delante de vocal, [[ne]] se convierte en [[n']]: [[Il n'a pas de voiture.]]</p><p>Después de la negación, [[un]], [[une]], [[des]] y [[du]] se convierten en [[de]]: [[J'ai du temps.]] → [[Je n'ai pas de temps.]]</p><p>Para preguntar, sube la entonación al final ([[Tu aimes le thé ?]]) o empieza con [[Est-ce que]]: [[Est-ce que vous habitez ici ?]]</p>`,
  ex:['No hablo inglés.','Él no tiene coche.','¿Te gusta el té?','¿Vivís aquí?'],
  q:['«No como carne»:','«No tengo tiempo»:']}
],
A2: [
 {t:'El passé composé con avoir',
  b:`<p>El passé composé cuenta acciones terminadas en el pasado (equivale al pretérito indefinido y también al perfecto). Se forma con [[avoir]] en presente + el participio: [[J'ai mangé.]] = Comí / He comido.</p><p>Participios: -er → [[-é]] ([[parlé]], [[mangé]]); -ir → [[-i]] ([[fini]]). Irregulares frecuentes: [[fait]] (faire), [[pris]] (prendre), [[vu]] (voir), [[eu]] (avoir), [[été]] (être), [[lu]] (lire), [[bu]] (boire).</p><p class="tip">La negación rodea a [[avoir]]: [[Je n'ai pas mangé.]]</p>`,
  ex:['Comí una manzana.','Vimos una película.','¿Has terminado tu trabajo?','Ella cogió el autobús.'],
  q:['«Compré un libro»:','«Él hizo los deberes»:']},
 {t:'El passé composé con être',
  b:`<p>Unos quince verbos de movimiento y cambio de estado usan [[être]] en lugar de avoir: [[aller]], [[venir]], [[arriver]], [[partir]], [[entrer]], [[sortir]], [[rester]], [[naître]], [[mourir]], [[tomber]], [[monter]], [[descendre]], [[retourner]], y también todos los verbos pronominales ([[se lever]]).</p><p>Con être el participio concuerda con el sujeto como un adjetivo: [[Il est allé.]] [[Elle est allée.]] [[Ils sont allés.]] [[Elles sont allées.]]</p>`,
  ex:['Fui al cine.','Ella llegó ayer.','Nos quedamos en casa.','Se fueron temprano.'],
  q:['«Ella vino»:','«Fuimos al mar»:']},
 {t:'El futuro próximo y los verbos irregulares',
  b:`<p>Para el futuro próximo se usa [[aller]] + infinitivo, igual que «ir a»: [[Je vais partir.]] = Voy a irme.</p><p>Verbos irregulares de uso diario:</p><div class="tblwrap"><table><tr><th></th><th>aller</th><th>faire</th><th>venir</th></tr><tr><td>je</td><td>[[vais]]</td><td>[[fais]]</td><td>[[viens]]</td></tr><tr><td>tu</td><td>[[vas]]</td><td>[[fais]]</td><td>[[viens]]</td></tr><tr><td>il / elle</td><td>[[va]]</td><td>[[fait]]</td><td>[[vient]]</td></tr><tr><td>nous</td><td>[[allons]]</td><td>[[faisons]]</td><td>[[venons]]</td></tr><tr><td>vous</td><td>[[allez]]</td><td>[[faites]]</td><td>[[venez]]</td></tr><tr><td>ils</td><td>[[vont]]</td><td>[[font]]</td><td>[[viennent]]</td></tr></table></div><p class="tip">El tiempo se expresa con [[faire]], como «hacer»: [[Il fait froid.]] = Hace frío.</p>`,
  ex:['Me voy mañana.','Vamos a comer en el restaurante.','Hoy hace frío.','Ella viene de Túnez.'],
  q:['«Voy a viajar»:','«nosotros hacemos» (faire):']},
 {t:'Los adjetivos y la comparación',
  b:`<p>El adjetivo concuerda con el sustantivo: [[-e]] para el femenino y [[-s]] para el plural: [[un pull vert]], [[une robe verte]], [[des yeux verts]].</p><p>La mayoría de los adjetivos van <b>detrás</b> del sustantivo: [[une robe rouge]]. Algunos cortos y frecuentes van delante: [[beau]], [[grand]], [[petit]], [[bon]], [[jeune]], [[vieux]], [[nouveau]]: [[une belle maison]].</p><p>Comparación: [[plus]] … [[que]] (más … que), [[moins]] … [[que]] (menos … que), [[aussi]] … [[que]] (tan … como). Superlativo: [[le plus grand]]. Irregular: [[bon]] → [[meilleur]] → [[le meilleur]].</p>`,
  ex:['Es una casa bonita.','Ella tiene los ojos verdes.','París es más grande que Lyon.','Es el mejor restaurante de la ciudad.'],
  q:['«un vestido rojo»:','«más grande que»:']}
],
B1: [
 {t:'El imparfait y el passé composé',
  b:`<p>El imparfait corresponde al pretérito imperfecto: describe el fondo, los hábitos y los estados. Toma la forma [[nous]] del presente, quita -ons y añade [[-ais]], [[-ais]], [[-ait]], [[-ions]], [[-iez]], [[-aient]]: [[nous habitons]] → [[j'habitais]]. Solo être es irregular: [[j'étais]].</p><p>El passé composé cuenta lo que pasó (un hecho), como el indefinido. Juntos: [[Il pleuvait quand je suis sorti.]] = Llovía cuando salí.</p><p class="tip">«Solía…» se dice con el imparfait: [[Avant, nous allions souvent à la plage.]]</p>`,
  ex:['Cuando era pequeño, vivía en el campo.','Llovía cuando salí.','Antes íbamos a menudo a la playa.'],
  q:['«Cuando era niño, jugaba al fútbol»:','«Estaba leyendo cuando sonó el teléfono»:']},
 {t:'Los pronombres complemento: le, la, lui, leur, y, en',
  b:`<p>Complemento directo: [[le]] (lo), [[la]] (la), [[les]] (los, las). Indirecto (a alguien): [[lui]] (le), [[leur]] (les). [[me]], [[te]], [[nous]], [[vous]] sirven para ambos.</p><p>El pronombre va <b>delante</b> del verbo: [[Je le vois.]] [[Je lui ai donné le livre.]]</p><p>[[y]] sustituye un lugar (allí): [[J'y vais.]] [[en]] sustituye «de eso, algo»: [[J'en veux.]] = Quiero (de eso).</p><p class="tip">[[téléphoner à]] lleva complemento indirecto: [[Je leur téléphone.]] = Les llamo.</p>`,
  ex:['Lo veo todos los días.','Le di el libro.','Voy allí mañana.'],
  q:['«La conozco»:','«Les llamo por teléfono»:']},
 {t:'El futuro y el condicional',
  b:`<p>El futuro simple: infinitivo + [[-ai]], [[-as]], [[-a]], [[-ons]], [[-ez]], [[-ont]], como en español: [[je finirai]], [[nous partirons]]. Raíces irregulares: [[ser-]] (être), [[aur-]] (avoir), [[ir-]] (aller), [[fer-]] (faire), [[pourr-]] (pouvoir), [[viendr-]] (venir).</p><p>El condicional usa la misma raíz con las terminaciones del imparfait: [[je voudrais]], [[nous partirions]]. Sirve para pedir con cortesía: [[Pourriez-vous m'aider ?]] y para aconsejar: [[À ta place, je partirais.]]</p>`,
  ex:['Mañana terminaré este trabajo.','Quisiera un café, por favor.','Yo que tú, me iría.'],
  q:['«Saldremos mañana»:','«¿Podría ayudarme?»:']}
],
B2: [
 {t:'El subjuntivo presente',
  b:`<p>Como en español, después de expresiones de necesidad, deseo, emoción y duda con [[que]] se usa el subjuntivo: [[Il faut que tu viennes.]] [[Je veux que vous soyez heureux.]]</p><p>Formación: la forma [[ils]] del presente sin -ent + [[-e]], [[-es]], [[-e]], [[-ions]], [[-iez]], [[-ent]]: [[ils finissent]] → [[que je finisse]]. Irregulares: [[que je sois]] (être), [[que j'aie]] (avoir), [[que je fasse]] (faire), [[que j'aille]] (aller), [[que je puisse]] (pouvoir).</p><p class="tip">Ojo: tras [[espérer]] (esperar) el francés usa el indicativo, no el subjuntivo.</p>`,
  ex:['Tienes que venir.','Quiero que seáis felices.','Me alegro de que estés aquí.'],
  q:['«Tengo que hacer los deberes»:','«Quiero que venga»:']},
 {t:'Los pronombres relativos: qui, que, où, dont',
  b:`<p>[[qui]] es el sujeto de la oración relativa: [[La femme qui parle est ma sœur.]]</p><p>[[que]] es el complemento: [[C'est le livre que je lis.]]</p><p>[[où]] sustituye un lugar o un tiempo: [[C'est la ville où je suis né.]]</p><p>[[dont]] sustituye «de + sustantivo» (del que, cuyo): [[Le film dont je parle]] (parler de).</p>`,
  ex:['Es el libro que estoy leyendo.','La mujer que habla es mi hermana.','Es la ciudad donde nací.'],
  q:['«El hombre que canta»:','«La película de la que hablo»:']},
 {t:'Las oraciones condicionales con si',
  b:`<p>Condición real: [[si]] + presente → futuro: [[Si tu viens, nous irons au parc.]]</p><p>Irreal en el presente: [[si]] + imparfait → condicional: [[Si j'avais le temps, je voyagerais.]] (donde el español usa el subjuntivo «tuviera»).</p><p>Irreal en el pasado: [[si]] + plus-que-parfait → condicional compuesto: [[Si j'avais su, je serais venu.]]</p><p class="tip">Nunca pongas el condicional justo después de [[si]]: «si j'aurais» es un error frecuente.</p>`,
  ex:['Si tuviera tiempo, viajaría.','Si vienes, iremos al parque.','Si lo hubiera sabido, habría venido.'],
  q:['«Si fuera rico, compraría una casa»:','«Si lo hubiera sabido, habría venido»:']}
],
C1: [
 {t:'La voz pasiva',
  b:`<p>La pasiva es [[être]] en cualquier tiempo + el participio, que concuerda con el sujeto: [[Le pont a été construit en 1900.]] [[La lettre a été envoyée.]] El agente se introduce con [[par]].</p><p>El francés evita a menudo la pasiva con [[on]] o con un verbo pronominal, como la pasiva refleja: [[Ce plat se mange froid.]] = Este plato se come frío. [[Le français se parle au Canada.]]</p>`,
  ex:['El puente fue construido en 1900.','Esta decisión se tomará mañana.','Este plato se come frío.'],
  q:['«La carta fue enviada»:','«En Canadá se habla francés»:']},
 {t:'El gerundio y el participio presente',
  b:`<p>El participio presente termina en [[-ant]]: toma la forma [[nous]] y cambia -ons por -ant: [[nous marchons]] → [[marchant]]. Irregulares: [[étant]], [[ayant]], [[sachant]].</p><p>El gérondif es [[en]] + participio y expresa simultaneidad, modo o condición, como el gerundio español: [[Il écoute de la musique en travaillant.]] [[En lisant, on apprend beaucoup.]]</p><p>Sin [[en]], el participio es de estilo escrito y expresa causa: [[Ne sachant pas quoi dire, il s'est tu.]]</p>`,
  ex:['Escucha música mientras trabaja.','Leyendo se aprende mucho.','No sabiendo qué decir, se calló.'],
  q:['«caminando»:','«Saliendo temprano, evitaremos los atascos»:']}
],
C2: [
 {t:'El passé simple',
  b:`<p>El passé simple es el pasado de la literatura y la historia; en la lengua hablada lo sustituye el passé composé. Hay que reconocerlo al leer.</p><p>Verbos en -er: [[-ai]], [[-as]], [[-a]], [[-âmes]], [[-âtes]], [[-èrent]] ([[il entra]]). En -ir / -re: [[-is]], [[-it]], [[-îmes]], [[-irent]] ([[il fit]], [[il s'assit]]). Otros en [[-us]]: [[il fut]], [[il eut]], [[ils vécurent]].</p>`,
  ex:['Entró en la habitación y se sentó.','Ella se sorprendió con la noticia.','Vivieron felices.'],
  q:['«él hizo» (faire):','«ellos fueron» (être):']},
 {t:'El subjuntivo tras conjunciones',
  b:`<p>Algunas conjunciones exigen siempre el subjuntivo: [[bien que]] (aunque), [[pour que]] (para que), [[avant que]] (antes de que), [[sans que]] (sin que), [[à condition que]] (a condición de que): [[Bien qu'il soit fatigué, il continue.]]</p><p>En estilo cuidado, tras [[avant que]], [[à moins que]] y los verbos de temor se añade un «ne expletivo» que <b>no</b> niega la frase: [[Partons avant qu'il ne pleuve.]] = Vámonos antes de que llueva.</p>`,
  ex:['Aunque está cansado, sigue.','Te lo digo para que lo sepas.','Vámonos antes de que llueva.'],
  q:['«Aunque está enferma, trabaja»:','«antes de que se vaya»:']}
]};
